<?php declare(strict_types=1); namespace Core\Console\Commands; use Core\Console\Command; use Core\Support\Str; final class KeyGenerateCommand extends Command { protected string $name = 'key:generate'; protected string $description = 'Generate an application key and write it to .env (APP_KEY).'; public function handle(array $args, array $options): int { $key = 'base64:' . base64_encode(random_bytes(32)); $envFile = $this->app->basePath('.env'); if (is_file($envFile)) { $contents = (string) file_get_contents($envFile); $contents = preg_replace('/^APP_KEY=.*$/m', 'APP_KEY=' . $key, $contents) ?? $contents; file_put_contents($envFile, $contents); } $this->success('APP_KEY set. ' . substr($key, 0, 16) . '…'); return 0; } } 